/* From Uiverse.io by vinodjangid07  - Tags: simple, card, cookies, accept, cookie card, policy */
.__UIV_SCOPE__ .cookies-card {
  width: 280px;
  height: fit-content;
  background-color: rgb(255, 250, 250);
  border-radius: 10px;
  border: 1px solid rgb(206, 206, 206);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px;
  gap: 15px;
  position: relative;
  font-family: Arial, Helvetica, sans-serif;
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.066);
}

.__UIV_SCOPE__ .cookie-heading {
  color: rgb(34, 34, 34);
  font-weight: 800;
}
.__UIV_SCOPE__ .cookie-para {
  font-size: 11px;
  font-weight: 400;
  color: rgb(51, 51, 51);
}
.__UIV_SCOPE__ .button-wrapper {
  width: 100%;
  height: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.__UIV_SCOPE__ .cookie-button {
  width: 50%;
  padding: 8px 0;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}
.__UIV_SCOPE__ .accept {
  background-color: rgb(34, 34, 34);
  color: white;
}
.__UIV_SCOPE__ .reject {
  background-color: #ececec;
  color: rgb(34, 34, 34);
}
.__UIV_SCOPE__ .accept:hover {
  background-color: rgb(0, 0, 0);
}
.__UIV_SCOPE__ .reject:hover {
  background-color: #ddd;
}
.__UIV_SCOPE__ .exit-button {
  position: absolute;
  top: 17px;
  right: 17px;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}
.__UIV_SCOPE__ .exit-button:hover {
  background-color: #ddd;
  color: white;
}
.__UIV_SCOPE__ .svgIconCross {
  height: 10px;
}
